#include "vivarium/vivarium.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace vivarium { namespace {
double clip(double v){if(!std::isfinite(v))throw std::invalid_argument("Actions must be finite");return std::clamp(v,-1.0,1.0);} void check(const std::vector<double>&a,std::size_t n){if(a.size()!=n)throw std::invalid_argument("Incorrect action vector size");for(double v:a)if(!std::isfinite(v))throw std::invalid_argument("Actions must be finite");}
}
PhysicsWorld2D::PhysicsWorld2D(WorldConfig2D c){set_config(c);} void PhysicsWorld2D::set_config(const WorldConfig2D&c){if(!(c.width>0&&c.height>0&&c.fixed_dt>0&&c.max_speed>0)||!std::isfinite(c.width+c.height+c.fixed_dt+c.max_speed+c.gravity.x+c.gravity.y))throw std::invalid_argument("Invalid world configuration");config_=c;} void PhysicsWorld2D::clear(){bodies_.clear();next_id_=1;} std::size_t PhysicsWorld2D::add_body(Body2D b){if(!(b.radius>0&&b.mass>0&&b.restitution>=0&&b.restitution<=1)||!std::isfinite(b.radius+b.mass+b.restitution+b.position.x+b.position.y+b.velocity.x+b.velocity.y))throw std::invalid_argument("Invalid body properties");b.id=next_id_++;bodies_.push_back(b);return bodies_.size()-1;} Body2D& PhysicsWorld2D::body(std::size_t i){return bodies_.at(i);} const Body2D& PhysicsWorld2D::body(std::size_t i)const{return bodies_.at(i);}
void PhysicsWorld2D::bounds(Body2D&b){if(b.fixed)return;const double r=b.radius;if(b.position.x<r){b.position.x=r;if(b.velocity.x<0)b.velocity.x=-b.velocity.x*b.restitution;}if(b.position.x>config_.width-r){b.position.x=config_.width-r;if(b.velocity.x>0)b.velocity.x=-b.velocity.x*b.restitution;}if(b.position.y<r){b.position.y=r;if(b.velocity.y<0)b.velocity.y=-b.velocity.y*b.restitution;}if(b.position.y>config_.height-r){b.position.y=config_.height-r;if(b.velocity.y>0)b.velocity.y=-b.velocity.y*b.restitution;}}
void PhysicsWorld2D::collide(Body2D&a,Body2D&b){Vec2 d=b.position-a.position;double d2=d.x*d.x+d.y*d.y,md=a.radius+b.radius;if(d2>=md*md||d2<1e-16)return;double len=std::sqrt(d2);Vec2 n{d.x/len,d.y/len};double ia=a.fixed?0:1/a.mass,ib=b.fixed?0:1/b.mass,sum=ia+ib;if(sum<=0)return;double pen=md-len;a.position+=n*(-pen*ia/sum);b.position+=n*(pen*ib/sum);Vec2 rel=b.velocity-a.velocity;double vn=rel.x*n.x+rel.y*n.y;if(vn<0){double impulse=-(1+std::min(a.restitution,b.restitution))*vn/sum;if(!a.fixed)a.velocity=a.velocity-n*(impulse*ia);if(!b.fixed)b.velocity+=n*(impulse*ib);}}
void PhysicsWorld2D::step(){double dt=config_.fixed_dt;for(auto&b:bodies_){if(b.fixed)continue;b.velocity+=config_.gravity*dt;double s2=b.velocity.x*b.velocity.x+b.velocity.y*b.velocity.y;if(s2>config_.max_speed*config_.max_speed)b.velocity=b.velocity*(config_.max_speed/std::sqrt(s2));b.position+=b.velocity*dt;bounds(b);}for(int k=0;k<3;++k){for(std::size_t i=0;i<bodies_.size();++i)for(std::size_t j=i+1;j<bodies_.size();++j)collide(bodies_[i],bodies_[j]);for(auto&b:bodies_)bounds(b);}}
BallPush::BallPush(std::size_t n):limit_(n){if(!n)throw std::invalid_argument("max_steps must be positive");reset(0);} Observation BallPush::reset(std::uint64_t s){rng_.reseed(s);steps_=0;closed_=false;WorldConfig2D c;c.gravity={0,0};c.width=10;c.height=6;c.fixed_dt=1./60;world_.set_config(c);world_.clear();world_.add_body({{1.2,3},{0,0},.3,1,.15,false,0});world_.add_body({{rng_.uniform(6,7.5),rng_.uniform(1.5,4.5)},{0,0},.55,2,.1,false,0});target_={9,3};return observe();} Observation BallPush::observe()const{auto&a=world_.body(0);auto&b=world_.body(1);return{a.position.x,a.position.y,a.velocity.x,a.velocity.y,b.position.x,b.position.y,b.velocity.x,b.velocity.y,target_.x,target_.y};} StepResult BallPush::step(const std::vector<double>&a){if(closed_)throw std::logic_error("Environment closed; reset before stepping");check(a,2);auto&agent=world_.body(0);double dt=world_.config().fixed_dt;agent.velocity.x+=clip(a[0])*8*dt;agent.velocity.y+=clip(a[1])*8*dt;agent.velocity=agent.velocity*.985;world_.step();++steps_;auto&b=world_.body(1);double d=std::hypot(target_.x-b.position.x,target_.y-b.position.y);bool ok=d<.65;StepResult r{observe(),-.01*d-.001+(ok?1:0),ok,steps_>=limit_&&!ok,{}};r.info["distance_to_target"]=d;r.info["success"]=ok;r.info["step_count"]=std::int64_t(steps_);return r;} EnvironmentSpec BallPush::spec()const{return{"BallPush-v0","Push a ball toward a target in a bounded 2D world",10,2};}
Navigate::Navigate(std::size_t n):limit_(n){if(!n)throw std::invalid_argument("max_steps must be positive");reset(0);} Observation Navigate::reset(std::uint64_t s){rng_.reseed(s);steps_=0;closed_=false;position_={rng_.uniform(.5,2),rng_.uniform(.5,2)};target_={9,9};return observe();} Observation Navigate::observe()const{return{position_.x,position_.y,target_.x,target_.y,target_.x-position_.x,target_.y-position_.y};} StepResult Navigate::step(const std::vector<double>&a){if(closed_)throw std::logic_error("Environment closed; reset before stepping");check(a,2);double old=std::hypot(target_.x-position_.x,target_.y-position_.y);position_.x=std::clamp(position_.x+clip(a[0])*.15,0.,10.);position_.y=std::clamp(position_.y+clip(a[1])*.15,0.,10.);++steps_;double d=std::hypot(target_.x-position_.x,target_.y-position_.y);bool ok=d<.35;StepResult r{observe(),old-d-.01+(ok?1:0),ok,steps_>=limit_&&!ok,{}};r.info["distance_to_target"]=d;r.info["success"]=ok;return r;} EnvironmentSpec Navigate::spec()const{return{"Navigate-v0","Move a point agent to a goal in a bounded 2D arena",6,2};}
PoleBalance::PoleBalance(std::size_t n):limit_(n){if(!n)throw std::invalid_argument("max_steps must be positive");reset(0);} Observation PoleBalance::reset(std::uint64_t s){rng_.reseed(s);angle_=rng_.uniform(-.04,.04);angular_velocity_=cart_position_=cart_velocity_=0;steps_=0;closed_=false;return observe();} Observation PoleBalance::observe()const{return{angle_,angular_velocity_,cart_position_,cart_velocity_};} StepResult PoleBalance::step(const std::vector<double>&a){if(closed_)throw std::logic_error("Environment closed; reset before stepping");check(a,1);double f=clip(a[0])*10,dt=1./60;double aa=9.81*std::sin(angle_)-.08*angular_velocity_+.025*f*std::cos(angle_),ca=(f-.1*cart_velocity_+.4*std::sin(angle_))/1.1;angular_velocity_+=aa*dt;angle_+=angular_velocity_*dt;cart_velocity_+=ca*dt;cart_position_+=cart_velocity_*dt;++steps_;bool fail=std::abs(angle_)>.45||std::abs(cart_position_)>2.4;StepResult r{observe(),fail?0.:1.,fail,steps_>=limit_&&!fail,{}};r.info["angle"]=angle_;return r;} EnvironmentSpec PoleBalance::spec()const{return{"PoleBalance-v0","Educational simplified inverted-pendulum task",4,1};}
StackBlocks::StackBlocks(std::size_t n):limit_(n){if(!n)throw std::invalid_argument("max_steps must be positive");reset(0);} Observation StackBlocks::reset(std::uint64_t s){rng_.reseed(s);steps_=height_=0;top_x_=placement_x_=5;closed_=false;return observe();} Observation StackBlocks::observe()const{return{double(height_),placement_x_,top_x_,double(steps_)/double(limit_),4.-double(height_),top_x_-placement_x_};} StepResult StackBlocks::step(const std::vector<double>&a){if(closed_)throw std::logic_error("Environment closed; reset before stepping");check(a,1);placement_x_=std::clamp(placement_x_+clip(a[0])*.25,0.,10.);++steps_;bool aligned=std::abs(placement_x_-top_x_)<.4;if(aligned){++height_;top_x_=placement_x_;placement_x_=std::clamp(top_x_+rng_.uniform(-.6,.6),0.,10.);}bool success=height_>=4;StepResult r{observe(),(aligned?.2:-.2)+(success?1.:0.),success||!aligned,steps_>=limit_&&!(success||!aligned),{}};r.info["height"]=std::int64_t(height_);r.info["placed"]=aligned;return r;} EnvironmentSpec StackBlocks::spec()const{return{"StackBlocks-v0","Align placements to stack four blocks",6,1};}
std::shared_ptr<Environment> make_environment(const std::string&id){if(id=="BallPush"||id=="BallPush-v0")return std::make_shared<BallPush>();if(id=="Navigate"||id=="Navigate-v0")return std::make_shared<Navigate>();if(id=="PoleBalance"||id=="PoleBalance-v0")return std::make_shared<PoleBalance>();if(id=="StackBlocks"||id=="StackBlocks-v0")return std::make_shared<StackBlocks>();throw std::invalid_argument("Unknown environment id: "+id);}
}
